    pass

solution:
def tidy(tasks, done):
    left = tasks[:]
    if done in left:
        left.remove(done)
    return sorted(left)

count = int(input())
prices = []
for _ in range(count):
    prices.append(int(input()))

above = 0
highest = prices[0]
for p in prices:
    if p > 10:
        above += 1
    if p > highest:
        highest = p
print(above)
print(highest)
